-- Daily quests rebalanced: required kill counts by target level / player level range, and a mixed
-- reward set (EXP, gold, potions/scrolls, upgrade materials, boxes, NP) in six tiers.
--
-- Safe to run more than once (pure UPDATEs by id, guarded by the first target monster so a row
-- that was repurposed in the admin panel is skipped) and safe on a live server: it only touches
-- kill_count / reward_N / count_N of daily_quests and clamps in-progress counters.
-- Formula, tiers and the before/after table: docs/DAILY_QUESTS.md.
--
-- Apply:  sudo -u postgres psql -d ko_server -v ON_ERROR_STOP=1 -f migrations/20261018140000_daily_quests_rebalance.sql
-- The last statement queues a hot reload ("daily_quests") for the running game server; without it the
-- new values load at the next restart (or save any daily quest in Admin panel -> Odul Merkezi).
BEGIN;

-- 1) every reward item must exist in the item table (abort the whole migration otherwise)
DO $$
DECLARE missing TEXT;
BEGIN
    SELECT string_agg(v.id::text, ', ') INTO missing
    FROM (VALUES (379016000),(379021000),(379154000),(379155000),(379156000),(379159000),(379160000),(379161000),(379162000),(379163000),(379164000),(379205000),(379221000),(389082000),(389196000),(800008000),(800024000),(800028000),(800029000),(800030000),(800076000),(800078000),(810011000),(810012000),(810015000),(810189000),(810192000),(810245000),(810246000),(810341000),(810691000),(810692000),(811010000),(811053000),(900000000),(900001000),(900002000),(900128000),(900129000),(999915000)) AS v(id)
    WHERE NOT EXISTS (SELECT 1 FROM item i WHERE i.num = v.id);
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'daily quest rebalance: reward items missing from item table: %', missing;
    END IF;
END $$;

-- 2) new kill counts + rewards
UPDATE daily_quests q SET
    kill_count = v.kills,
    reward_1 = v.r1, count_1 = v.c1,
    reward_2 = v.r2, count_2 = v.c2,
    reward_3 = v.r3, count_3 = v.c3,
    reward_4 = v.r4, count_4 = v.c4
