-- 3) players who already had more kills than the new (lower) target would otherwise sit at "full"
--    without completing; leave them one kill short.
UPDATE user_daily_quest u
SET kill_count = GREATEST(q.kill_count - 1, 0)
FROM daily_quests q
WHERE q.id = u.quest_id AND u.status = 2 AND u.kill_count >= q.kill_count;

-- 4) hot reload on the running game server (admin command queue)
INSERT INTO admin_command (command, args)
SELECT 'reload', '{"what":"daily_quests"}'::jsonb
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'admin_command');

COMMIT;
